#include <stdio.h>
#include <string.h>
#include <math.h>
#include <stdlib.h>
int main() {
    char s[100]; if (scanf("%s", s) != 1) return 0;
    int p = strlen(s);
    long long n = atoll(s), sum = 0;
    for (int i = 0; i < p; i++) {
        long long term = 1, d = s[i] - '0';
        for (int k = 0; k < p; k++) term *= d;
        sum += term;
    }
    puts(sum == n ? "Yes" : "No");
    return 0;
}

