public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            int p = s.length();
            long n = Long.parseLong(s), sum = 0;
            for (char c : s.toCharArray()) {
                long term = 1, d = c - '0';
                for (int k = 0; k < p; k++) term *= d;
                sum += term;
            }
            System.out.println(sum == n ? "Yes" : "No");
        }
    }
}

